(()=>{const root=document.querySelector('.updated-copy');root.querySelectorAll('table').forEach(t=>{let labels=[...t.querySelectorAll('th')].map(x=>x.textContent);t.querySelectorAll('tbody tr').forEach(tr=>[...tr.children].forEach((td,i)=>td.dataset.label=labels[i]||''));});const menu=document.querySelector('.menu-toggle');menu?.addEventListener('click',()=>{const nav=document.querySelector('#main-nav');const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);nav?.classList.toggle('open',open);if(nav)nav.style.display=open?'flex':'';});root.querySelectorAll('img').forEach(img=>img.addEventListener('click',()=>{const dlg=document.createElement('dialog');dlg.className='copy-zoom';const full=img.cloneNode();const close=document.createElement('button');close.textContent='×';close.setAttribute('aria-label','إغلاق');close.onclick=()=>dlg.close();dlg.append(full,close);dlg.addEventListener('close',()=>dlg.remove());document.body.append(dlg);dlg.showModal();}));const langs=[...root.querySelectorAll('img')].filter(x=>/design-1v/.test(x.src));if(langs.length===2){const host=langs[0].parentElement;langs.forEach((img,i)=>{img.hidden=i!==0;const b=document.createElement('button');b.className='copy-language';b.textContent=i===0?'العربية':'English';b.setAttribute('aria-pressed',i===0);b.onclick=()=>{langs.forEach((x,j)=>x.hidden=j!==i);host.querySelectorAll('.copy-language').forEach((x,j)=>x.setAttribute('aria-pressed',j===i));};host.insertBefore(b,langs[0]);});}if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const ob=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.animate([{opacity:.7,translate:'0 12px'},{opacity:1,translate:'0 0'}],{duration:450});ob.unobserve(e.target);}}),{threshold:.1});root.querySelectorAll('section').forEach(x=>ob.observe(x));}})();
